-- ══════════════════════════════════════════════════════════════════════════
-- KANONİK KAYITLAR — equipment_models
--
-- `on conflict (slug) do update`: paket güncellendiğinde aynı ürün yeniden
-- yazılabilsin. Üç slug tohum katalogda zaten var (astronomik-cls-ccd,
-- idas-nbz, zwo-duo-band).
--
-- ÇAKIŞMADA EDİTÖR KAZANIYOR. `summary`, `production_status` ve
-- `data_confidence` yalnızca BOŞSA (ya da 'bilinmiyor'sa) yazılıyor:
-- pakette 99 üründen 74'ü doğrulanmamış ve doğrulanmamış bir satırın,
-- birinin oturup girdiği bilgiyi ezmesi kabul edilemez. `specs` ise
-- birleştiriliyor — paketin getirdiği spektral alanlar ekleniyor, mevcut
-- anahtarlar (backfocus, filtre kalınlığı) yerinde kalıyor.
-- ══════════════════════════════════════════════════════════════════════════

insert into public.equipment_models (slug, brand_id, category_id, model, summary, specs, production_status, data_confidence) values ('antlia-lrgb-dark', 'antlia', 'filtre', 'LRGB Dark', 'Antlia geniş bant filtresi.', '{"Kategori":"Geniş bant","Pazar sınıfı":"Geniş bant","Ürün tipi":"Set / aile"}'::jsonb, 'bilinmiyor', 'inceleme-gerekli')
  on conflict (slug) do update set brand_id = excluded.brand_id, category_id = excluded.category_id, model = excluded.model, summary = coalesce(public.equipment_models.summary, excluded.summary), specs = public.equipment_models.specs || excluded.specs, production_status = case when public.equipment_models.production_status = 'bilinmiyor' then excluded.production_status else public.equipment_models.production_status end, data_confidence = coalesce(public.equipment_models.data_confidence, excluded.data_confidence);
